<script setup lang="ts">
import { ref, onMounted, onUnmounted, computed } from 'vue';
import { api, USER_ID } from '@/api/client';
const props=defineProps<{campaignId:string;topicId:string;projectId:string;title:string}>();
const emit=defineEmits<{close:[]}>();
type Version={figureCount?:number;id:string;createdAt:string;author:string;compiled:boolean;pageCount?:number;commit?:string;error?:string;versioningError?:string;message?:string;researchStatus:string};
type DocumentState={versions:Version[];busy:boolean;localPath:string;error?:string;latestPdfVersion?:string};
const state=ref<DocumentState>({versions:[],busy:false,localPath:''}),selected=ref(''),source=ref(''),original=ref(''),error=ref(''),notice=ref(''),feedback=ref(''),saving=ref(false),log=ref(''),showLog=ref(false);
const dirty=computed(()=>source.value!==original.value);
const current=computed(()=>state.value.versions.find(v=>v.id===selected.value));
const illustratedVersion=computed(()=>state.value.versions.find(v=>v.compiled && (v.figureCount ?? 0)>0));
const base=`/api/reviews/${props.campaignId}/topics/${props.topicId}/document`;
function file(name:string){return `${base}/versions/${selected.value}/${name}?userId=${encodeURIComponent(USER_ID)}`;}
let timer:ReturnType<typeof setInterval>|undefined,loading=false;
async function choose(id:string){if(dirty.value){error.value='当前有未保存编辑，请先保存或点击“放弃本次编辑”。';return;}selected.value=id;showLog.value=false;try{source.value=String((await api.get(file('main.tex'),{responseType:'text'})).data);original.value=source.value;error.value='';}catch(e){error.value=String(e);}}
async function load(){if(loading)return;loading=true;try{state.value=(await api.get(base,{params:{userId:USER_ID}})).data;if(!selected.value&&state.value.versions.length)await choose(state.value.versions[0]!.id);}catch(e){error.value=String(e);}finally{loading=false;}}
async function sync(){try{await api.post(`${base}/sync`,{userId:USER_ID});await load();}catch(e){error.value=String(e);}}
async function save(){saving.value=true;error.value='';try{await api.post(`${base}/save`,{userId:USER_ID,basedOn:selected.value,expectedHead:state.value.versions[0]?.id,source:source.value,message:'本地LaTeX编辑'});original.value=source.value;notice.value='已提交本地编译，旧版保留。完成后可从左侧打开新版本。';await load();}catch(e){error.value=String(e);}finally{saving.value=false;}}
async function logs(){try{log.value=String((await api.get(file('compile.log'),{responseType:'text'})).data);showLog.value=!showLog.value;}catch(e){error.value=String(e);}}
async function sendFeedback(){if(!feedback.value.trim())return;try{await api.post(`/api/projects/${props.projectId}/guidance`,{target:'review-draft',text:`本地LaTeX阅读反馈（基于版本${selected.value}）：${feedback.value}`,requestId:`latex-${crypto.randomUUID()}`});feedback.value='';notice.value='指导已保存，Ekina 后续修订时读取；不会因此重复启动当前任务。';}catch(e){error.value=String(e);}}
function close(){if(dirty.value){error.value='还有未保存编辑，请先保存或放弃本次编辑。';return;}emit('close');}
function key(e:KeyboardEvent){if(e.key==='Escape')close();}
onMounted(()=>{void load();timer=setInterval(load,4000);document.addEventListener('keydown',key);});
onUnmounted(()=>{clearInterval(timer);document.removeEventListener('keydown',key);});
</script>
<template>
 <Teleport to="body"><div class="latex-overlay"><section class="latex-dialog" role="dialog" aria-modal="true" :aria-label="`${title} · LaTeX工作台`">
  <header><div><strong>{{title}}</strong><small>本地 LaTeX 工作台 · 自动保存 Ekina 新稿 · Git 版本历史 · {{state.busy?'正在本地排版':'就绪'}}</small></div><div><button :disabled="saving||state.busy||!selected" @click="save">保存新版本并编译</button><button @click="close" aria-label="关闭LaTeX工作台">关闭</button></div></header>
  <p v-if="error||state.error" role="alert" class="alert">{{error||state.error}}</p><p v-if="notice" class="notice">{{notice}}</p>
  <div class="latex-body"><aside><h3>文稿版本</h3><button :disabled="state.busy" @click="sync">同步 Ekina 最新稿</button><button v-if="illustratedVersion && illustratedVersion.id!==selected" @click="choose(illustratedVersion.id)">打开最近有图版本（{{illustratedVersion.figureCount}}幅）</button><p v-if="!state.versions.length">完整草稿形成后自动生成 LaTeX 和 PDF。</p><button v-for="v in state.versions" :key="v.id" class="version" :class="{selected:v.id===selected}" @click="choose(v.id)"><b>{{v.author}} · {{v.compiled?'PDF已生成':'编译未完成'}} · {{v.figureCount ? v.figureCount+'幅图' : '文字版'}}</b><span>{{new Date(v.createdAt).toLocaleString()}}</span><small>{{v.commit?.slice(0,8) || '版本记录待确认'}}</small></button><details><summary>本地存放位置</summary><code>{{state.localPath}}</code></details></aside>
   <main><div class="tools"><span>{{dirty?'有未保存修改':'源码已保存'}} · {{current?.author}}</span><button v-if="dirty" @click="source=original">放弃本次编辑</button><button v-if="current" @click="logs">编译日志</button><a v-if="current" :href="file('main.tex')" target="_blank">源码</a><a v-if="current?.compiled" :href="file('main.pdf')" target="_blank">打开 PDF</a></div>
    <p v-if="current?.error||current?.versioningError" class="alert">{{current.error||current.versioningError}}</p>
    <p v-if="current && !current.figureCount" class="notice">当前选择的是文字版本，尚未嵌入图片。请从左侧选择标有图片数量的版本；历史文字稿会保留。</p><div class="split"><textarea v-model="source" :disabled="!selected||saving" aria-label="LaTeX源码" spellcheck="false"/><div v-if="current?.compiled && current.pageCount" :key="selected" class="pdf-pages" aria-label="综述PDF逐页预览"><figure v-for="n in current.pageCount" :key="n"><img :src="file(`page-${String(n).padStart(3,'0')}.png`)" :alt="`PDF第${n}页`" loading="lazy"/><figcaption>{{n}} / {{current.pageCount}}</figcaption></figure></div><div v-else class="empty">{{current?.error || (current?.compiled?'此历史版本可通过“打开 PDF”阅读。':'选择一个版本查看 PDF；编译成功不代表科研内容已验收。')}}</div></div>
    <pre v-if="showLog" class="logs">{{log}}</pre><footer><input v-model="feedback" placeholder="给 Ekina 的修改意见，例如：第二节先解释机制，再比较路线" aria-label="文稿修改意见"/><button :disabled="!feedback.trim()" @click="sendFeedback">保存指导</button></footer>
   </main>
  </div>
 </section></div></Teleport>
</template>
<style scoped>
.latex-overlay{position:fixed;inset:0;z-index:10010;background:#152a3e99;display:grid;place-items:center;padding:16px}.latex-dialog{width:min(1600px,100%);height:95vh;background:#f7f9fb;color:#263c49;border-radius:14px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 70px #0004}header{display:flex;justify-content:space-between;gap:20px;align-items:center;background:white;padding:16px 22px;border-bottom:1px solid #dbe3e9}header small{display:block;margin-top:6px;color:#647788}button{padding:8px 11px;border:1px solid #c5d3dc;border-radius:6px;background:white;color:#2d5066;cursor:pointer;font:inherit}button:disabled{opacity:.5;cursor:default}header button{margin-left:8px}.latex-body{display:flex;flex:1;min-height:0}aside{width:215px;flex-shrink:0;padding:16px;overflow:auto;font-size:12px}aside h3{font-size:14px}.version{display:block;width:100%;text-align:left;margin-top:10px;line-height:1.6}.version span,.version small{display:block;color:#708393}.selected{border-color:#388098;background:#eaf3f5}aside code{overflow-wrap:anywhere}aside details{margin-top:18px}main{flex:1;min-width:0;display:flex;flex-direction:column}.tools{display:flex;align-items:center;gap:12px;padding:9px 12px;font-size:12px}.tools span{margin-right:auto}.tools a{color:#286881}.split{display:flex;min-height:0;flex:1;gap:1px;background:#d8e1e8}.split textarea{width:45%;resize:none;min-width:0;border:0;outline:none;padding:18px;font:13px/1.7 Consolas,'Microsoft YaHei',monospace;color:#233b4c;background:#fcfdfd;tab-size:2}.pdf-pages{width:55%;overflow:auto;background:#dce4e9;padding:14px;box-sizing:border-box}.pdf-pages figure{margin:0 0 18px}.pdf-pages img{display:block;width:100%;height:auto;background:white;box-shadow:0 3px 12px #152b3c33}.pdf-pages figcaption{text-align:center;font-size:11px;color:#536979;padding-top:8px}.empty{flex:1;padding:30px;color:#728394;background:#f1f5f8}footer{display:flex;gap:10px;padding:12px;background:white}footer input{flex:1;min-width:0;padding:10px;border:1px solid #cbd8e0;border-radius:6px}.alert,.notice{padding:9px 16px;margin:0;font-size:13px}.alert{background:#fff0ec;color:#93422f}.notice{background:#eaf5f0;color:#28634b}.logs{max-height:190px;overflow:auto;margin:0;padding:16px;font-size:12px;white-space:pre-wrap;background:#172b38;color:#e4edf4}@media(max-width:900px){aside{width:155px}.split{flex-direction:column}.split textarea,.pdf-pages{width:100%;height:50%;box-sizing:border-box}.latex-overlay{padding:4px}}
</style>
